HEALTH_VARIATIONAL_HEARTBEAT_STALE_SECONDS = HEARTBEAT_STALE_SECONDS * 2
HEALTH_QUOTE_DEGRADED_SECONDS = 30.0
HEALTH_QUOTE_STALE_SECONDS = 90.0
HEALTH_TRADE_EVENT_DEGRADED_SECONDS = 60.0
HEALTH_TRADE_EVENT_STALE_SECONDS = 180.0
HEALTH_LIGHTER_BOOK_DEGRADED_SECONDS = 10.0
HEALTH_LIGHTER_BOOK_STALE_SECONDS = 30.0
TRADE_EVENT_STARTUP_GRACE_SECONDS = 5.0


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def to_decimal(value: Any) -> Decimal | None:
    if value is None:
        return None
    try:
        return Decimal(str(value))
    except Exception:
        return None


def decimal_to_str(value: Decimal | None) -> str | None:
    if value is None:
        return None
    return format(value, "f")


def margin_usage_percent(
    requirement: Decimal | None,
    equity: Decimal | None,
) -> Decimal | None:
    if requirement is None or equity is None or equity <= 0:
        return None
    return requirement / equity * Decimal("100")


def adaptive_margin_thresholds(
    *,
    maintenance_requirement_usd: Decimal | None,
    current_notional_usd: Decimal,
    equity_usd: Decimal | None,
    target_notional_usd: Decimal,
    max_venue_leverage: Decimal,
    warning_pct: Decimal,
    block_entry_pct: Decimal,
    reduce_pct: Decimal,
    emergency_pct: Decimal,
    fallback_maintenance_rate: Decimal | None = None,
) -> dict[str, Any]:
    maintenance_rate = (
        maintenance_requirement_usd / current_notional_usd
        if maintenance_requirement_usd is not None
        and maintenance_requirement_usd >= 0
        and current_notional_usd > 0
        else None
    )
    maintenance_rate_source = "reported"
    if maintenance_rate is None and fallback_maintenance_rate is not None:
        maintenance_rate = fallback_maintenance_rate
        maintenance_rate_source = "conservative_fallback"
    baseline_at_max_leverage_pct = (
        maintenance_rate * max_venue_leverage * Decimal("100")
        if maintenance_rate is not None
        else None
    )
    projected_usage_pct = (
        maintenance_rate * target_notional_usd / equity_usd * Decimal("100")
        if maintenance_rate is not None
        and equity_usd is not None
        and equity_usd > 0
        else None
    )
    baseline = baseline_at_max_leverage_pct or Decimal("0")
    effective_emergency = min(
        Decimal("95"), max(emergency_pct, baseline + Decimal("40"))
    )
    effective_reduce = min(
        effective_emergency - Decimal("1"),
        max(reduce_pct, baseline + Decimal("30")),
    )
    effective_block = min(
        effective_reduce - Decimal("1"),
        max(block_entry_pct, baseline + Decimal("20")),
    )
    effective_warning = min(
        effective_block - Decimal("1"),
        max(warning_pct, baseline + Decimal("10")),
    )
    return {
        "maintenance_rate": maintenance_rate,
        "maintenance_rate_source": maintenance_rate_source,
        "baseline_at_max_leverage_pct": baseline_at_max_leverage_pct,
        "projected_usage_pct": projected_usage_pct,
        "warning_pct": effective_warning,
        "block_entry_pct": effective_block,
        "reduce_pct": effective_reduce,
        "emergency_pct": effective_emergency,
    }


def account_risk_context(
    *,
    variational_metrics: dict[str, Any],
    lighter_metrics: dict[str, Any],
    current_notional_usd: Decimal,
    proposed_notional_usd: Decimal | None,
    max_venue_leverage: Decimal,
    margin_warning_pct: Decimal,
    margin_block_entry_pct: Decimal,
    margin_reduce_pct: Decimal,
    margin_emergency_pct: Decimal,
    balance_warning_ratio: Decimal,
    balance_block_ratio: Decimal,
) -> dict[str, Any]:
    var_equity = to_decimal(variational_metrics.get("equity_usd"))
    lighter_equity = to_decimal(lighter_metrics.get("equity_usd"))
    variational_balance = to_decimal(variational_metrics.get("balance_usd"))
    variational_upnl = to_decimal(variational_metrics.get("upnl_usd"))
    lighter_collateral = to_decimal(lighter_metrics.get("collateral_usd"))
    lighter_upnl = to_decimal(lighter_metrics.get("unrealized_pnl_usd"))
    var_maintenance = to_decimal(
        variational_metrics.get("maintenance_margin_usage_pct")
    )
    lighter_maintenance = to_decimal(
        lighter_metrics.get("maintenance_margin_usage_pct")
    )
    balance_ratio = (
        min(var_equity, lighter_equity) / max(var_equity, lighter_equity)
        if var_equity is not None
        and lighter_equity is not None
        and var_equity > 0
        and lighter_equity > 0
        else None
    )
    equity_imbalance_pct = (
        abs(var_equity - lighter_equity)
        / ((var_equity + lighter_equity) / Decimal("2"))
        * Decimal("100")
        if var_equity is not None
        and lighter_equity is not None
        and var_equity > 0
        and lighter_equity > 0
        else None
    )
    rebalance_plan = None
    if (
        var_equity is not None
        and lighter_equity is not None
        and var_equity > 0
        and lighter_equity > 0
    ):
        rebalance_plan = build_rebalance_plan(
            variational_equity_usd=var_equity,
            lighter_equity_usd=lighter_equity,
            block_ratio=balance_warning_ratio,
            target_imbalance_pct=(
                LIVE_INVENTORY_EQUITY_REBALANCE_TARGET_IMBALANCE_PCT
            ),
        )
    target_notional = (
        proposed_notional_usd
        if proposed_notional_usd is not None
        else current_notional_usd
    )
    var_margin = adaptive_margin_thresholds(
        maintenance_requirement_usd=to_decimal(
            variational_metrics.get("maintenance_margin_requirement_usd")
        ),
        current_notional_usd=current_notional_usd,
        equity_usd=var_equity,
        target_notional_usd=target_notional,
        max_venue_leverage=max_venue_leverage,
        warning_pct=margin_warning_pct,
        block_entry_pct=margin_block_entry_pct,
        reduce_pct=margin_reduce_pct,
        emergency_pct=margin_emergency_pct,
        fallback_maintenance_rate=(
            LIVE_INVENTORY_VARIATIONAL_MAINTENANCE_RATE_FALLBACK
        ),
    )
    lighter_margin = adaptive_margin_thresholds(
        maintenance_requirement_usd=to_decimal(
            lighter_metrics.get("maintenance_margin_requirement_usd")
        ),
        current_notional_usd=current_notional_usd,
        equity_usd=lighter_equity,
        target_notional_usd=target_notional,
        max_venue_leverage=max_venue_leverage,
        warning_pct=margin_warning_pct,
        block_entry_pct=margin_block_entry_pct,
        reduce_pct=margin_reduce_pct,
        emergency_pct=margin_emergency_pct,
        fallback_maintenance_rate=(
            LIVE_INVENTORY_LIGHTER_MAINTENANCE_RATE_FALLBACK
        ),
    )
    var_effective_usage = (
        var_margin["projected_usage_pct"]
        if proposed_notional_usd is not None
        and var_margin["projected_usage_pct"] is not None
        else var_maintenance
    )
    lighter_effective_usage = (
        lighter_margin["projected_usage_pct"]
        if proposed_notional_usd is not None
        and lighter_margin["projected_usage_pct"] is not None
        else lighter_maintenance
    )
    maintenance_values = [
        value
        for value in (var_effective_usage, lighter_effective_usage)
        if value is not None
    ]
    max_maintenance = max(maintenance_values) if maintenance_values else None
    var_leverage = (
        target_notional / var_equity
        if var_equity is not None and var_equity > 0
        else None
    )
    lighter_leverage = (
        target_notional / lighter_equity
        if lighter_equity is not None and lighter_equity > 0
        else None
    )
    max_leverage = max(
        (value for value in (var_leverage, lighter_leverage) if value is not None),
        default=None,
    )

    action = "normal"
    reason = "account_risk_normal"
    if var_equity is None or lighter_equity is None:
        action = "block_entry"
        reason = "account_equity_unavailable"
    elif (
        proposed_notional_usd is not None
        and max_leverage is not None
        and max_leverage > max_venue_leverage
    ):
        action = "block_entry"
        reason = "venue_leverage_exceeds_hard_entry_limit"
    elif any(
        usage is not None and usage >= thresholds["emergency_pct"]
        for usage, thresholds in (
            (var_effective_usage, var_margin),
            (lighter_effective_usage, lighter_margin),
        )
    ):
        action = "emergency_exit"
        reason = "maintenance_margin_usage_emergency"
    elif any(
        usage is not None and usage >= thresholds["reduce_pct"]
        for usage, thresholds in (
            (var_effective_usage, var_margin),
            (lighter_effective_usage, lighter_margin),
        )
    ):
        action = "force_reduce"
        reason = "maintenance_margin_usage_reduce"
    elif any(
        usage is not None and usage >= thresholds["block_entry_pct"]
        for usage, thresholds in (
            (var_effective_usage, var_margin),
            (lighter_effective_usage, lighter_margin),
        )
    ):
        action = "block_entry"
        reason = "maintenance_margin_usage_blocks_entry"
    elif balance_ratio is not None and balance_ratio < balance_block_ratio:
        action = "block_entry"
        reason = "venue_equity_imbalance_blocks_entry"
    elif (
        proposed_notional_usd is None
        and max_leverage is not None
        and max_leverage > max_venue_leverage
    ):
        # The hard 5x limit applies to new notional. Once filled, a small
        # adverse mark move can mechanically report >5x; maintenance headroom
        # controls reduction so a full 5x entry is not immediately unwound.
        action = "warning"
        reason = "venue_leverage_above_entry_cap_monitoring_margin"
    elif any(
        usage is not None and usage >= thresholds["warning_pct"]
        for usage, thresholds in (
            (var_effective_usage, var_margin),
            (lighter_effective_usage, lighter_margin),
        )
    ):
        action = "warning"
        reason = "maintenance_margin_usage_warning"
    elif balance_ratio is not None and balance_ratio < balance_warning_ratio:
        action = "warning"
        reason = "venue_equity_imbalance_warning"

    return {
        "risk_action": action,
        "risk_reason": reason,
        "current_notional_usd": decimal_to_str(current_notional_usd),
        "proposed_notional_usd": decimal_to_str(proposed_notional_usd),
        "variational_equity_usd": decimal_to_str(var_equity),
        "variational_balance_usd": decimal_to_str(
            variational_metrics.get("balance_usd")
        ),
        "variational_upnl_usd": decimal_to_str(
            variational_metrics.get("upnl_usd")
        ),
        "variational_equity_formula": variational_metrics.get(
            "equity_formula"
        ),
        "variational_realized_balance_usd": decimal_to_str(
            variational_balance - variational_upnl
            if variational_balance is not None and variational_upnl is not None
            else None
        ),
        "lighter_equity_usd": decimal_to_str(lighter_equity),
        "lighter_collateral_usd": decimal_to_str(lighter_collateral),
        "lighter_unrealized_pnl_usd": decimal_to_str(lighter_upnl),
        "lighter_realized_balance_usd": decimal_to_str(lighter_collateral),
        "lighter_realized_balance_check_usd": decimal_to_str(
            lighter_equity - lighter_collateral - lighter_upnl
            if lighter_equity is not None
            and lighter_collateral is not None
            and lighter_upnl is not None
            else None
        ),
        "combined_equity_usd": decimal_to_str(
            var_equity + lighter_equity
            if var_equity is not None and lighter_equity is not None
            else None
        ),
        "equity_balance_ratio": decimal_to_str(balance_ratio),
        "equity_imbalance_pct": decimal_to_str(equity_imbalance_pct),
        "rebalance_recommended": (
            bool(rebalance_plan.get("required")) if rebalance_plan else None
        ),
        "rebalance_from_venue": (
            rebalance_plan.get("source_venue") if rebalance_plan else None
        ),
        "rebalance_to_venue": (
            rebalance_plan.get("destination_venue") if rebalance_plan else None
        ),
        "rebalance_suggested_amount_usd": (
            rebalance_plan.get("amount_usd") if rebalance_plan else None
        ),
        "rebalance_target_imbalance_pct": decimal_to_str(
            LIVE_INVENTORY_EQUITY_REBALANCE_TARGET_IMBALANCE_PCT
        ),
        "variational_maintenance_margin_usage_pct": decimal_to_str(
            var_maintenance
        ),
        "lighter_maintenance_margin_usage_pct": decimal_to_str(
            lighter_maintenance
        ),
        "max_maintenance_margin_usage_pct": decimal_to_str(max_maintenance),
        "variational_effective_margin_usage_pct": decimal_to_str(
            var_effective_usage
        ),
        "lighter_effective_margin_usage_pct": decimal_to_str(
            lighter_effective_usage
        ),
        "variational_maintenance_rate": decimal_to_str(
            var_margin["maintenance_rate"]
        ),
        "lighter_maintenance_rate": decimal_to_str(
            lighter_margin["maintenance_rate"]
        ),
        "variational_maintenance_rate_source": var_margin[
            "maintenance_rate_source"
        ],
        "lighter_maintenance_rate_source": lighter_margin[
            "maintenance_rate_source"
        ],
        "variational_baseline_margin_usage_at_max_leverage_pct": decimal_to_str(
            var_margin["baseline_at_max_leverage_pct"]
        ),
        "lighter_baseline_margin_usage_at_max_leverage_pct": decimal_to_str(
            lighter_margin["baseline_at_max_leverage_pct"]
        ),
        "variational_effective_margin_warning_pct": decimal_to_str(
            var_margin["warning_pct"]
        ),
        "variational_effective_margin_block_entry_pct": decimal_to_str(
            var_margin["block_entry_pct"]
        ),
        "variational_effective_margin_reduce_pct": decimal_to_str(
            var_margin["reduce_pct"]
        ),
        "variational_effective_margin_emergency_pct": decimal_to_str(
            var_margin["emergency_pct"]
        ),
        "lighter_effective_margin_warning_pct": decimal_to_str(
            lighter_margin["warning_pct"]
        ),
        "lighter_effective_margin_block_entry_pct": decimal_to_str(
            lighter_margin["block_entry_pct"]
        ),
        "lighter_effective_margin_reduce_pct": decimal_to_str(
            lighter_margin["reduce_pct"]
        ),
        "lighter_effective_margin_emergency_pct": decimal_to_str(
            lighter_margin["emergency_pct"]
        ),
        "variational_projected_leverage": decimal_to_str(var_leverage),
        "lighter_projected_leverage": decimal_to_str(lighter_leverage),
        "max_projected_venue_leverage": decimal_to_str(max_leverage),
        "max_venue_leverage": decimal_to_str(max_venue_leverage),
        "margin_warning_pct": decimal_to_str(margin_warning_pct),
        "margin_block_entry_pct": decimal_to_str(margin_block_entry_pct),
        "margin_reduce_pct": decimal_to_str(margin_reduce_pct),
        "margin_emergency_pct": decimal_to_str(margin_emergency_pct),
        "balance_warning_ratio": decimal_to_str(balance_warning_ratio),
        "balance_block_ratio": decimal_to_str(balance_block_ratio),
    }


def account_risk_notification_transition(
    *,
    current_action: str,
    current_reason: str,
    pending_reason: str | None,
    warning_confirm_count: int,
    recovery_confirm_count: int,
    risk_action: str,
    risk_reason: str,
    context: dict[str, Any],
    warning_confirm_samples: int = (
        LIVE_INVENTORY_ACCOUNT_RISK_NOTIFICATION_CONFIRM_SAMPLES
    ),
    recovery_confirm_samples: int = (
        LIVE_INVENTORY_ACCOUNT_RISK_NOTIFICATION_RECOVERY_SAMPLES
    ),
    imbalance_clear_buffer: Decimal = (
        LIVE_INVENTORY_ACCOUNT_RISK_IMBALANCE_CLEAR_BUFFER
    ),
) -> dict[str, Any]:
    """Debounce advisory account-risk notifications without weakening safety actions."""
    current_action = str(current_action or "normal")
    current_reason = str(current_reason or "account_risk_normal")
    risk_action = str(risk_action or "normal")
    risk_reason = str(risk_reason or "account_risk_normal")
    warning_confirm_samples = max(1, int(warning_confirm_samples))
    recovery_confirm_samples = max(1, int(recovery_confirm_samples))

    critical_actions = {"force_reduce", "emergency_exit"}
    advisory_actions = {"warning", "block_entry"}
    event: str | None = None

    if risk_action in critical_actions:
        if current_action != risk_action or current_reason != risk_reason:
            event = "alert"
        return {
            "notification_action": risk_action,
            "notification_reason": risk_reason,
            "notification_pending_reason": None,
            "notification_warning_confirm_count": 0,
            "notification_recovery_confirm_count": 0,
            "notification_event": event,
        }

    if risk_action in advisory_actions:
        if current_action in critical_actions:
            return {
                "notification_action": current_action,
                "notification_reason": current_reason,
                "notification_pending_reason": None,
                "notification_warning_confirm_count": 0,
                "notification_recovery_confirm_count": 0,
                "notification_event": None,
            }
        if current_action in advisory_actions and current_reason == risk_reason:
            return {
                "notification_action": current_action,
                "notification_reason": current_reason,
                "notification_pending_reason": None,
                "notification_warning_confirm_count": warning_confirm_count,
                "notification_recovery_confirm_count": 0,
                "notification_event": None,
            }

        next_warning_count = (
            warning_confirm_count + 1
            if pending_reason == risk_reason
            else 1
        )
        if next_warning_count < warning_confirm_samples:
            return {
                "notification_action": (
                    current_action
                    if current_action in advisory_actions
                    else "normal"
                ),
                "notification_reason": (
                    current_reason
                    if current_action in advisory_actions
                    else "account_risk_normal"
                ),
                "notification_pending_reason": risk_reason,
                "notification_warning_confirm_count": next_warning_count,
                "notification_recovery_confirm_count": 0,
                "notification_event": None,
            }
        return {
            "notification_action": risk_action,
            "notification_reason": risk_reason,
            "notification_pending_reason": None,
            "notification_warning_confirm_count": next_warning_count,
            "notification_recovery_confirm_count": 0,
            "notification_event": "alert",
        }

    if current_action in critical_actions or current_action in advisory_actions:
        clear = True
        if current_reason in {
            "venue_equity_imbalance_warning",
            "venue_equity_imbalance_blocks_entry",
        }:
            balance_ratio = to_decimal(context.get("equity_balance_ratio"))
            warning_ratio = to_decimal(context.get("balance_warning_ratio"))
            clear = bool(
                balance_ratio is not None
                and warning_ratio is not None
                and balance_ratio
                >= min(Decimal("0.99"), warning_ratio + imbalance_clear_buffer)
            )
        if not clear:
            return {
                "notification_action": current_action,
                "notification_reason": current_reason,
                "notification_pending_reason": None,
                "notification_warning_confirm_count": warning_confirm_count,
                "notification_recovery_confirm_count": 0,
                "notification_event": None,
            }
        next_recovery_count = recovery_confirm_count + 1
        if next_recovery_count < recovery_confirm_samples:
            return {
                "notification_action": current_action,
                "notification_reason": current_reason,
                "notification_pending_reason": None,
                "notification_warning_confirm_count": warning_confirm_count,
                "notification_recovery_confirm_count": next_recovery_count,
                "notification_event": None,
            }
        event = "recovered"

    return {
        "notification_action": "normal",
        "notification_reason": "account_risk_normal",
        "notification_pending_reason": None,
        "notification_warning_confirm_count": 0,
        "notification_recovery_confirm_count": 0,
        "notification_event": event,
    }


def is_retryable_lighter_account_read_error(exc: Exception) -> bool:
    """Retry only transient transport failures and server-side errors."""
    if isinstance(exc, (asyncio.TimeoutError, TimeoutError, OSError)):
        return True

    for attribute in ("status", "status_code", "http_status"):
        value = getattr(exc, attribute, None)
        if isinstance(value, (list, tuple)) and value:
            value = value[0]
        try:
            status = int(value)
        except (TypeError, ValueError):
            continue
        if 500 <= status <= 599:
            return True
        if status:
            return False

    response = getattr(exc, "http_resp", None)
    try:
        status = int(getattr(response, "status", 0) or 0)
    except (TypeError, ValueError):
        status = 0
    if 500 <= status <= 599:
        return True
    if status:
        return False

    match = re.search(r"\b([45][0-9]{2})\b", str(exc))
    if match:
        return 500 <= int(match.group(1)) <= 599

    error_name = type(exc).__name__.lower()
    error_text = str(exc).lower()
    return any(
        marker in error_name or marker in error_text
        for marker in (
            "timeout",
            "timed out",
            "connection",
            "disconnect",
            "connector",
            "temporarily unavailable",
        )
    )


def account_snapshot_freshness(
    published_at: Any,
    *,
    now: datetime | None = None,
    max_age_seconds: float = LIVE_INVENTORY_VARIATIONAL_ACCOUNT_MAX_AGE_SECONDS,
) -> dict[str, Any]:
    observed_at = now or datetime.now(timezone.utc)
    parsed: datetime | None = None
    if isinstance(published_at, datetime):
        parsed = published_at
    elif published_at not in (None, ""):
        try:
            parsed = datetime.fromisoformat(str(published_at).replace("Z", "+00:00"))
        except ValueError:
            parsed = None
    if parsed is not None:
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        else:
            parsed = parsed.astimezone(timezone.utc)
    age_seconds = (
        (observed_at.astimezone(timezone.utc) - parsed).total_seconds()
        if parsed is not None
        else None
    )
    fresh = bool(
        age_seconds is not None
        and age_seconds >= -5.0
        and age_seconds <= max_age_seconds
    )
    return {
        "published_at": parsed.isoformat() if parsed is not None else None,
        "age_seconds": age_seconds,
        "max_age_seconds": max_age_seconds,
        "fresh": fresh,
        "reason": (
            "fresh"
            if fresh
            else "published_at_missing_or_invalid"
            if parsed is None
            else "published_at_in_future"
            if age_seconds is not None and age_seconds < -5.0
            else "snapshot_stale"
        ),
    }


def v4_real_gradient_thresholds(
    *,
    history_values: list[Decimal],
    base_threshold_bps: Decimal,
    entry_execution_reserve_bps: Decimal,
    actual_market_noise_bps: Decimal | None = None,
    incremental_depth_cost_bps: Decimal | None = None,
    recent_pair_execution_error_bps: Decimal | None = None,
) -> list[Decimal]:
    # The absolute pair-execution error is already represented in the base
    # execution reserve. Reusing it as every tier's spacing double-counts the
    # same risk and makes upper tiers effectively unreachable.
    spacing_bps = max(
        LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_MIN_TIER_SPACING_BPS,
        abs(actual_market_noise_bps or Decimal("0")),
        abs(incremental_depth_cost_bps or Decimal("0")),
    )
    thresholds = [base_threshold_bps]
    for percentile in LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_PERCENTILES[1:]:
        historical = VariationalToLighterRuntime.live_inventory_basis_v4_percentile(
            history_values,
            percentile,
        )
        candidate = (
            historical + entry_execution_reserve_bps
            if historical is not None
            else thresholds[-1] + spacing_bps
        )
        thresholds.append(
            max(
                candidate,
                thresholds[-1] + spacing_bps,
            )
        )
    return thresholds


def v4_real_gradient_eligible_tier(
    edge_bps: Decimal,
    thresholds_bps: list[Decimal],
) -> int:
    return sum(1 for threshold in thresholds_bps if edge_bps >= threshold)


def v4_exact_rfq_entry_threshold(
    passive_threshold_bps: Decimal | None,
    directional_bias_bps: Decimal | None,
) -> Decimal | None:
    """Translate a passive trigger into the exact-RFQ decision domain."""
    if passive_threshold_bps is None:
        return None
    return passive_threshold_bps + (directional_bias_bps or Decimal("0"))


def v4_exact_rfq_gradient_thresholds(
    passive_thresholds_bps: Iterable[Decimal],
    directional_bias_bps: Decimal | None,
) -> list[Decimal]:
    """Apply the same RFQ translation to every real-gradient tier."""
    bias_bps = directional_bias_bps or Decimal("0")
    return [threshold + bias_bps for threshold in passive_thresholds_bps]


def v4_real_gradient_confirmed_tier(
    tier_window: Iterable[int],
    *,
    latest_tier: int,
) -> int:
    """Return the highest tier crossed by the latest and 2 of 3 samples."""
    values = [max(0, int(value)) for value in tier_window]
    if not values or latest_tier <= 0:
        return 0
    return max(
        (
            tier
            for tier in range(1, latest_tier + 1)
            if sum(1 for value in values if value >= tier)
            >= LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_ENTRY_CONFIRM_SAMPLES
        ),
        default=0,
    )


def v4_real_gradient_entry_activation(
    tier_window: Iterable[int],
    *,
    latest_tier: int,
) -> tuple[int, str]:
    """Return normal confirmation or a capped high-tier single-sample probe."""
    confirmed_tier = v4_real_gradient_confirmed_tier(
        tier_window,
        latest_tier=latest_tier,
    )
    if confirmed_tier > 0:
        return confirmed_tier, "two_of_three"
    if latest_tier >= LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_STRONG_SINGLE_MIN_TIER:
        return 1, "strong_single_probe"
    return 0, "pending_two_of_three"


def v4_real_gradient_sample_move_decision(
    *,
    sample_move_ok: bool,
    strong_single_probe: bool,
    refresh_entry_quote_enabled: bool,
) -> str:
    """Choose whether a basis move blocks or gets one high-tier recheck."""
    if sample_move_ok:
        return "normal"
    if strong_single_probe and refresh_entry_quote_enabled:
        return "shock_recheck"
    return "block"


def v4_real_gradient_slot_caps(
    *,
    variational_equity_usd: Decimal | None,
    lighter_equity_usd: Decimal | None,
    child_notional_usd: Decimal,
    max_venue_leverage: Decimal,
    tier_count: int = LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_MAX_TIERS,
) -> list[int] | None:
    """Build cumulative child-order slots without weakening the 5x hard cap."""
    if (
        variational_equity_usd is None
        or lighter_equity_usd is None
        or variational_equity_usd <= 0
        or lighter_equity_usd <= 0
        or child_notional_usd <= 0
        or max_venue_leverage <= 0
        or tier_count <= 0
    ):
        return None
    smaller_equity = min(variational_equity_usd, lighter_equity_usd)
    hard_slots = int(
        (smaller_equity * max_venue_leverage / child_notional_usd).to_integral_value(
            rounding=ROUND_DOWN
        )
    )
    return [
        min(
            hard_slots,
            int(
                (
                    smaller_equity * Decimal(tier) / child_notional_usd
                ).to_integral_value(rounding=ROUND_HALF_UP)
            ),
        )
        for tier in range(1, tier_count + 1)
    ]


def v4_real_gradient_capacity_notional_usd(
    *,
    tier: int,
    variational_equity_usd: Decimal | None,
    lighter_equity_usd: Decimal | None,
    max_venue_leverage: Decimal,
    child_notional_usd: Decimal = Decimal("20"),
) -> Decimal | None:
    if tier <= 0:
        return None
    caps = v4_real_gradient_slot_caps(
        variational_equity_usd=variational_equity_usd,
        lighter_equity_usd=lighter_equity_usd,
        child_notional_usd=child_notional_usd,
        max_venue_leverage=max_venue_leverage,
    )
    if caps is None:
        return None
    return Decimal(caps[min(tier, len(caps)) - 1]) * child_notional_usd


def v4_real_gradient_elastic_capacity_child_lots(
    *,
    tier: int,
    slot_caps: list[int] | None,
    open_child_lots: int,
    enabled: bool,
    addon_eligible: bool,
) -> int | None:
    """Allow one guarded reserve slot after the first cumulative tier is full."""
    if not slot_caps or tier <= 0:
        return None
    base_capacity = slot_caps[min(tier, len(slot_caps)) - 1]
    if (
        not enabled
        or not addon_eligible
        or tier != 1
        or open_child_lots < base_capacity
    ):
        return base_capacity
    hard_next_capacity = slot_caps[min(2, len(slot_caps)) - 1]
    return min(
        hard_next_capacity,
        base_capacity + LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_ELASTIC_MAX_BORROWED_CHILD_LOTS,
    )


def v4_real_gradient_lot_groups(
    lots: Iterable[dict[str, Any]],
) -> list[tuple[int, list[dict[str, Any]]]]:
    """Group lots by their own entry tier, ordered from highest risk down."""
    groups: dict[int, list[dict[str, Any]]] = {}
    for lot in lots:
        tier = max(1, int(lot.get("entry_gradient_tier") or 1))
        groups.setdefault(tier, []).append(lot)
    return [(tier, groups[tier]) for tier in sorted(groups, reverse=True)]


def maintenance_drain_uses_individual_legacy_exits(
    *,
    requested: bool,
    lots: Iterable[dict[str, Any]],
) -> bool:
    """Keep unlabeled pre-gradient lots independent during a maintenance drain."""
    return bool(
        requested
        and any(lot.get("entry_gradient_tier") is None for lot in lots)
    )


def live_inventory_state_status(
    *,
    open_lots: Iterable[Any],
    pending_actions: Iterable[Any],
) -> str:
    if any(True for _ in open_lots):
        return "open"
    if any(True for _ in pending_actions):
        return "pending"
    return "flat"


def maintenance_control_targets_runtime(
    control: dict[str, Any],
    *,
    process_id: int,
    run_id: str,
    asset: str,
) -> bool:
    if str(control.get("action") or "") != "drain_after_flat":
        return False
    if str(control.get("status") or "") != "requested":
        return False
    try:
        target_pid = int(control.get("target_pid"))
    except (TypeError, ValueError):
        return False
    if target_pid != process_id:
        return False
    target_run_id = str(control.get("target_run_id") or "").strip()
    if target_run_id and target_run_id != run_id:
        return False
    return str(control.get("asset") or "").upper() == asset.upper()


def v4_partial_detier_selection(
    *,
    lots: list[dict[str, Any]],
    current_tier: int,
    variational_equity_usd: Decimal | None,
    lighter_equity_usd: Decimal | None,
    max_venue_leverage: Decimal,
) -> dict[str, Any]:
    notionals: list[tuple[dict[str, Any], Decimal]] = []
    for lot in lots:
        qty = to_decimal(lot.get("qty"))
        entry_price = to_decimal(lot.get("entry_var_fill_price"))
        if qty is None or qty <= 0 or entry_price is None or entry_price <= 0:
            return {"ready": False, "reason": "invalid_lot_notional"}
        notionals.append((lot, qty * entry_price))
    current_notional = sum((value for _, value in notionals), Decimal("0"))
    tiers = sorted(
        {
            max(1, int(lot.get("entry_gradient_tier") or 1))
            for lot, _ in notionals
        },
        reverse=True,
    )
    if not tiers:
        return {
            "ready": False,
            "reason": "no_gradient_tier_lots",
            "current_notional_usd": decimal_to_str(current_notional),
        }
    selected_tier = tiers[0]
    selected = [
        lot
        for lot, _ in notionals
        if max(1, int(lot.get("entry_gradient_tier") or 1)) == selected_tier
    ]
    selected_notional = sum(
        (notional for lot, notional in notionals if lot in selected),
        Decimal("0"),
    )
    remaining_notional = current_notional - selected_notional
    return {
        "ready": bool(selected),
        "reason": None if selected else "no_gradient_tier_lots",
        "selected_gradient_tier": selected_tier,
        "current_market_tier": current_tier,
        "tier_independent_exit": True,
        "selected_lot_ids": [
            str(lot.get("lot_id")) for lot in selected
        ],
        "remaining_lot_ids": [
            str(lot.get("lot_id"))
            for lot, _ in notionals
            if lot not in selected
        ],
        "current_notional_usd": decimal_to_str(current_notional),
        "selected_notional_usd": decimal_to_str(selected_notional),
        "remaining_notional_usd": decimal_to_str(remaining_notional),
        "current_tier": current_tier,
    }


def v4_weekend_regime_context(now: float) -> dict[str, Any]:
    current = datetime.fromtimestamp(now, tz=timezone.utc)
    seconds_in_week = (
        current.weekday() * 86400
        + current.hour * 3600
        + current.minute * 60
        + current.second
    )
    weekend_start = 5 * 86400
    weekend_end = 7 * 86400
    distances = {
        "weekend_start": abs(seconds_in_week - weekend_start),
        "weekend_end": min(abs(seconds_in_week - weekend_end), seconds_in_week),
    }
    transition_name, transition_distance = min(
        distances.items(), key=lambda item: item[1]
    )
    transition_active = (
        transition_distance <= LIVE_INVENTORY_BASIS_V4_WEEKEND_TRANSITION_SECONDS
    )
    return {
        "v4_market_regime": "weekend" if current.weekday() >= 5 else "weekday",
        "v4_weekend_transition": transition_name if transition_active else None,
        "v4_weekend_transition_active": transition_active,
        "v4_weekend_transition_distance_seconds": transition_distance,
        "v4_weekend_transition_window_seconds": (
            LIVE_INVENTORY_BASIS_V4_WEEKEND_TRANSITION_SECONDS
        ),
    }


def extract_variational_account_metrics(payload: Any) -> dict[str, Decimal | str | None]:
    if not isinstance(payload, dict):
        return {
            "balance_usd": None,
            "upnl_usd": None,
            "equity_usd": None,
            "equity_formula": None,
            "initial_margin_requirement_usd": None,
            "maintenance_margin_requirement_usd": None,
            "initial_margin_usage_pct": None,
            "maintenance_margin_usage_pct": None,
        }
    result = payload.get("result")
    if isinstance(result, dict):
        payload = result
    pool = payload.get("pool_portfolio_result")
    if isinstance(pool, dict):
        payload = pool
    balance = to_decimal(payload.get("balance"))
    upnl = to_decimal(payload.get("upnl"))
    # This portfolio endpoint's balance already includes mark-to-market PnL.
    # Keep upnl as a diagnostic component; adding it would count it twice.
    equity = balance
    formula = "balance_includes_upnl" if balance is not None else None
    margin_usage = payload.get("margin_usage")
    if not isinstance(margin_usage, dict):
        margin_usage = {}
    initial_margin = to_decimal(
        margin_usage.get("initial_margin")
        or payload.get("initial_margin_requirement")
    )
    maintenance_margin = to_decimal(
        margin_usage.get("maintenance_margin")
        or payload.get("maintenance_margin_requirement")
    )
    return {
        "balance_usd": balance,
        "upnl_usd": upnl,
        "equity_usd": equity,
        "equity_formula": formula,
        "initial_margin_requirement_usd": initial_margin,
        "maintenance_margin_requirement_usd": maintenance_margin,
        "initial_margin_usage_pct": margin_usage_percent(initial_margin, equity),
        "maintenance_margin_usage_pct": margin_usage_percent(
            maintenance_margin, equity
        ),
    }


def extract_lighter_account_metrics(payload: Any) -> dict[str, Decimal | str | None]:
    if not isinstance(payload, dict):
        return {
            "collateral_usd": None,
            "available_balance_usd": None,
            "total_asset_value_usd": None,
            "equity_usd": None,
            "unrealized_pnl_usd": None,
            "equity_formula": None,
            "initial_margin_requirement_usd": None,
            "maintenance_margin_requirement_usd": None,
            "initial_margin_usage_pct": None,
            "maintenance_margin_usage_pct": None,
        }
    accounts = payload.get("accounts")
    account = accounts[0] if isinstance(accounts, list) and accounts else None
    if not isinstance(account, dict):
        return {
            "collateral_usd": None,
            "available_balance_usd": None,
            "total_asset_value_usd": None,
            "equity_usd": None,
            "unrealized_pnl_usd": None,
            "equity_formula": None,
            "initial_margin_requirement_usd": None,
            "maintenance_margin_requirement_usd": None,
            "initial_margin_usage_pct": None,
            "maintenance_margin_usage_pct": None,
        }
    collateral = to_decimal(account.get("collateral"))
    available = to_decimal(account.get("available_balance"))
    total_asset_value = to_decimal(account.get("total_asset_value"))
    equity = total_asset_value if total_asset_value is not None else collateral
    positions = account.get("positions")
    position_upnl_values = [
        to_decimal(position.get("unrealized_pnl"))
        for position in positions
        if isinstance(position, dict)
    ] if isinstance(positions, list) else []
    position_upnl = (
        sum(position_upnl_values, Decimal("0"))
        if isinstance(positions, list)
        and all(value is not None for value in position_upnl_values)
        else None
    )
    unrealized_pnl = position_upnl
    if (
        unrealized_pnl is None
        and total_asset_value is not None
        and collateral is not None
    ):
        unrealized_pnl = total_asset_value - collateral
    initial_margin = to_decimal(account.get("cross_initial_margin_requirement"))
    maintenance_margin = to_decimal(
        account.get("cross_maintenance_margin_requirement")
    )
    return {
        "collateral_usd": collateral,
        "available_balance_usd": available,
        "total_asset_value_usd": total_asset_value,
        "equity_usd": equity,
        "unrealized_pnl_usd": unrealized_pnl,
        "equity_formula": (
            "total_asset_value"
            if total_asset_value is not None
            else "collateral"
            if collateral is not None
            else None
        ),
        "initial_margin_requirement_usd": initial_margin,
        "maintenance_margin_requirement_usd": maintenance_margin,
        "initial_margin_usage_pct": margin_usage_percent(initial_margin, equity),
        "maintenance_margin_usage_pct": margin_usage_percent(
            maintenance_margin, equity
        ),
    }


def json_log_default(value: Any) -> Any:
    if isinstance(value, Decimal):
        return decimal_to_str(value)
    raise TypeError(
        f"Object of type {type(value).__name__} is not JSON serializable"
    )


def bounded_text(value: str, *, max_chars: int = 500) -> str:
    if len(value) <= max_chars:
        return value
    return f"{value[:max_chars]}... [truncated original_chars={len(value)}]"


def parse_decimal_csv(value: str | None) -> list[Decimal]:
    if not value:
        return []
    values: list[Decimal] = []
    for part in str(value).split(","):
        text = part.strip()
        if not text:
            continue
        parsed = Decimal(text)
        if parsed > 0:
            values.append(parsed)
    return values


VARIATIONAL_API_AMOUNT_QUANTUM = Decimal("0.000001")
VARIATIONAL_API_AMOUNT_QUANTUM_BY_ASSET = {
    "ETH": Decimal("0.00001"),
    "SOL": Decimal("0.001"),
}


def variational_api_amount_to_str(value: Decimal, *, asset: str | None = None) -> str:
    quantum = VARIATIONAL_API_AMOUNT_QUANTUM_BY_ASSET.get(str(asset or "").upper(), VARIATIONAL_API_AMOUNT_QUANTUM)
    return decimal_to_str(value.quantize(quantum, rounding=ROUND_DOWN)) or "0"


def elapsed_ms_str(start_monotonic: float | None) -> str:
    if start_monotonic is None:
        return "-"
    return f"{(time.monotonic() - start_monotonic) * 1000:.3f}"


def elapsed_ms_between_str(start_monotonic: float | None, end_monotonic: float | None) -> str:
    value = elapsed_ms(start_monotonic, end_monotonic)
    if value is None:
        return "-"
    return f"{value:.3f}"


def clean_state_value(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip()
    if not text or text.lower() == "none":
        return ""
    return text


def decimal_percent_to_bps(value: Decimal | None) -> Decimal | None:
    return percent_to_bps(value)


def find_open_paper_opportunity_ids(path: Path | None) -> list[str]:
    if path is None or not path.exists():
        return []

    open_ids: set[str] = set()
    try:
        with path.open("r", encoding="utf-8") as handle:
            for raw_line in handle:
                line = raw_line.strip()
                if not line:
                    continue
                try:
                    row = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if row.get("record_kind") != "paper_opportunity":
                    continue
                opportunity_id = str(row.get("opportunity_id", "")).strip()
                if not opportunity_id:
                    continue
                status = str(row.get("status", "")).strip()
                if status == "paper_entered":
                    open_ids.add(opportunity_id)
                elif status == "paper_closed":
                    open_ids.discard(opportunity_id)
    except OSError:
        return []
    return sorted(open_ids)


def first_decimal_from_keys(payload: dict[str, Any], keys: tuple[str, ...]) -> Decimal | None:
    for key in keys:
        if key in payload:
            value = to_decimal(payload.get(key))
            if value is not None:
                return value
    return None


def nested_dicts(payload: dict[str, Any]) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = [payload]
    for key in ("data", "payload", "quote", "indicative", "prices", "result"):
        value = payload.get(key)
        if isinstance(value, dict):
            items.append(value)
    return items


def _pid_is_running(pid: int) -> bool:
    if pid <= 0:
        return False
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    return True


def acquire_instance_lock(lock_path: Path) -> int:
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(
        {
            "pid": os.getpid(),
            "created_at": utc_now(),
            "argv": list(os.sys.argv),
        },
        ensure_ascii=True,
    )

    while True:
        try:
            fd = os.open(str(lock_path), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            try:
                raw = lock_path.read_text(encoding="utf-8")
                existing = json.loads(raw)
            except Exception:
                existing = {}

            existing_pid = int(existing.get("pid", 0) or 0)
            if existing_pid and _pid_is_running(existing_pid):
                raise RuntimeError(
                    (
                        "Another main.py instance is already running "
                        f"(pid={existing_pid}, lock_file={lock_path}). Stop it before starting a new one."
                    )
                )

            with contextlib.suppress(FileNotFoundError):
                lock_path.unlink()
            continue

        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                handle.write(payload)
        except Exception:
            with contextlib.suppress(FileNotFoundError):
                lock_path.unlink()
            raise
        return os.getpid()


def release_instance_lock(lock_path: Path, owner_pid: int) -> None:
    try:
        raw = lock_path.read_text(encoding="utf-8")
        existing = json.loads(raw)
    except FileNotFoundError:
        return
    except Exception:
        existing = {}

    existing_pid = int(existing.get("pid", 0) or 0)
    if existing_pid not in {0, owner_pid}:
        return

    with contextlib.suppress(FileNotFoundError):
        lock_path.unlink()


def resolve_variational_ticker(ticker: str) -> str:
    return VARIATIONAL_TICKER_OVERRIDES.get(ticker.upper(), ticker.upper())


def resolve_lighter_ticker(variational_asset: str) -> str:
    asset = variational_asset.upper()
    return VARIATIONAL_ASSET_TO_LIGHTER_TICKER.get(asset, asset)


def required_env(name: str) -> str:
    value = os.getenv(name, "").strip()
    if not value:
        raise RuntimeError(f"{name} is not set")
    return value


def required_int_env(name: str) -> int:
    value = required_env(name)
    try:
        return int(value)
    except ValueError as exc:
        raise RuntimeError(f"{name} must be an integer, got: {value}") from exc


def env_flag(name: str) -> bool:
    value = os.getenv(name, "").strip().lower()
    return value in {"1", "true", "yes", "on"}


def spread_value(aggressive_buy_ask: Decimal | None, aggressive_sell_bid: Decimal | None) -> Decimal | None:
    if aggressive_buy_ask is None or aggressive_sell_bid is None:
        return None
    return aggressive_sell_bid - aggressive_buy_ask


def spread_percent(diff: Decimal | None, denominator: Decimal | None) -> Decimal | None:
    if diff is None or denominator is None or denominator == 0:
        return None
    return (diff / denominator) * Decimal("100")


def book_spread_percent(bid: Decimal | None, ask: Decimal | None) -> Decimal | None:
    if bid is None or ask is None:
        return None
    mid = (bid + ask) / Decimal("2")
    if mid == 0:
        return None
    return ((ask - bid) / mid) * Decimal("100")


def basis_points_diff(value: Decimal | None, reference: Decimal | None) -> Decimal | None:
    if value is None or reference is None or reference == 0:
        return None
    return (abs(value - reference) / reference) * Decimal("10000")


def elapsed_ms(start: float | None, end: float | None) -> Decimal | None:
    if start is None or end is None:
        return None
    return Decimal(str(max(0.0, (end - start) * 1000)))


def elapsed_iso_ms(start_iso: str | None, end_iso: str | None) -> Decimal | None:
    if not start_iso or not end_iso:
        return None
    with contextlib.suppress(Exception):
        start = datetime.fromisoformat(start_iso.replace("Z", "+00:00"))
        end = datetime.fromisoformat(end_iso.replace("Z", "+00:00"))
        return Decimal(str((end - start).total_seconds() * 1000))
    return None


def parse_utc_iso(value: Any) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def normalize_variational_status(status: str) -> str:
    lowered = status.strip().lower()
    if lowered in {"confirmed", "fill", "filled", "executed", "execution", "cleared"}:
        return "filled"
    return lowered


@dataclass(slots=True)
class OrderLifecycle:
    trade_key: str
    trade_id: str
    side: str
    qty: Decimal
    asset: str
    mode: str
    last_variational_status: str

    var_fill_price: Decimal | None = None
    var_fill_ts_iso: str | None = None
    synthetic_eager_fill: bool = False
    matched_variational_trade_id: str | None = None
    auto_live_cycle_id: int | None = None
    auto_live_role: str | None = None
    auto_live_merge_path: str | None = None

    lighter_side: str | None = None
    lighter_client_order_id: int | None = None
    lighter_submit_transport: str | None = None
    lighter_order_mode: str | None = None
