    async def append_live_inventory_log(self, event_type: str, payload: dict[str, Any]) -> None:
        enriched_payload = {
            "record_kind": "live_inventory",
            "mode": self.mode,
            "execution_mode": "dry_decision" if self.live_inventory_dry_decisions else "live",
            "run_id": getattr(self, "live_inventory_run_id", "unknown"),
            "schema_version": getattr(self, "live_inventory_schema_version", "1"),
            "strategy_version": getattr(self, "live_inventory_strategy_version", "legacy"),
            "strategy_variant": getattr(self, "live_inventory_strategy_variant", "legacy"),
            "config_hash": getattr(self, "live_inventory_config_hash", None),
            "cycle_id": payload.get("cycle_id", payload.get("lot_id")),
            **payload,
        }
        await self.append_order_log(event_type, enriched_payload)
        notifier = getattr(self, "telegram_notifier", None)
        if (
            notifier is not None
            and not getattr(self, "live_inventory_dry_decisions", False)
            and event_type not in LIVE_INVENTORY_WATCHDOG_OWNED_NOTIFICATION_EVENTS
        ):
            try:
                notifier.enqueue(event_type, enriched_payload)
            except Exception as exc:
                self.logger.warning(
                    "telegram_notification_enqueue_failed event=%s error=%s",
                    event_type,
                    type(exc).__name__,
                )
        if (
            not getattr(self, "live_inventory_dry_decisions", False)
            and event_type
            in {"live_inventory_entered", "live_inventory_exited"}
        ):
            self.schedule_live_inventory_account_snapshot(
                stage=(
                    "entry_confirmed"
                    if event_type == "live_inventory_entered"
                    else "exit_confirmed_flat"
                ),
                asset=str(
                    payload.get("asset") or self.live_inventory_state_asset()
                ),
                lot_id=payload.get("lot_id"),
            )

    async def append_live_inventory_internal_log(
        self,
        event_type: str,
        payload: dict[str, Any],
    ) -> None:
        """Write diagnostics without sending a user-facing notification."""
        enriched_payload = {
            "record_kind": "live_inventory",
            "mode": self.mode,
            "execution_mode": "dry_decision" if self.live_inventory_dry_decisions else "live",
            "run_id": getattr(self, "live_inventory_run_id", "unknown"),
            "schema_version": getattr(self, "live_inventory_schema_version", "1"),
            "strategy_version": getattr(self, "live_inventory_strategy_version", "legacy"),
            "strategy_variant": getattr(self, "live_inventory_strategy_variant", "legacy"),
            "config_hash": getattr(self, "live_inventory_config_hash", None),
            "cycle_id": payload.get("cycle_id", payload.get("lot_id")),
            **payload,
        }
        await self.append_order_log(event_type, enriched_payload)

    def should_log_live_inventory_basis_state(self, payload: dict[str, Any]) -> bool:
        if not getattr(self, "live_inventory_basis_v4_mode", False):
            return True
        edge = to_decimal(
            payload.get("v4_signal_edge_bps")
            if payload.get("v4_signal_edge_bps") is not None
            else payload.get("short_edge_bps")
        )
        threshold = to_decimal(payload.get("v4_entry_threshold_bps"))
        crossing = bool(
            edge is not None and threshold is not None and edge >= threshold
        )
        previous_crossing = bool(
            getattr(self, "live_inventory_last_basis_state_crossing", False)
        )
        self.live_inventory_last_basis_state_crossing = crossing
        now = time.monotonic()
        # Keep both edges of a crossing so offline diagnostics can measure
        # how long a rejected opportunity remained executable.
        if crossing != previous_crossing:
            self.live_inventory_last_basis_state_log_monotonic = now
            return True
        # Full-rate basis samples are stored separately. Keep operational
        # snapshots less frequent so the execution ledger stays compact.
        interval = (
            30.0
            if crossing or getattr(self, "live_inventory_open_lots", [])
            else 120.0
        )
        last = float(getattr(self, "live_inventory_last_basis_state_log_monotonic", 0.0) or 0.0)
        if now - last < interval:
            return False
        self.live_inventory_last_basis_state_log_monotonic = now
        return True

    def should_log_live_inventory_negative_direction_shadow(self) -> bool:
        now = time.monotonic()
        interval = 60.0 if getattr(self, "live_inventory_open_lots", []) else 300.0
        last = float(
            getattr(
                self,
                "live_inventory_negative_direction_shadow_last_monotonic",
                0.0,
            )
            or 0.0
        )
        if now - last < interval:
            return False
        self.live_inventory_negative_direction_shadow_last_monotonic = now
        return True

    async def maybe_auto_stop_completed_v4_cycle(
        self,
        final_pnl_payload: dict[str, Any] | None = None,
    ) -> bool:
        if final_pnl_payload is not None:
            self.live_inventory_last_final_pnl_payload = dict(final_pnl_payload)
        if (
            not getattr(self, "live_inventory_basis_v4_mode", False)
            or getattr(self, "live_inventory_dry_decisions", False)
            or getattr(self, "live_inventory_open_lots", [])
            or getattr(
                self,
                "live_inventory_v4_exit_reconciliation_lot_ids",
                set(),
            )
        ):
            return False
        completed_cycles = int(getattr(self, "live_inventory_completed_cycles", 0))
        max_cycles = int(getattr(self, "live_inventory_max_cycles", 1))
        final_cycle = max_cycles > 0 and completed_cycles >= max_cycles
        if final_cycle and getattr(self, "live_inventory_cycle_report_emitted", False):
            return False
        final_payload = getattr(self, "live_inventory_last_final_pnl_payload", None)
        if not final_payload:
            return False
        lot_id = self.live_inventory_normalized_lot_id(
            final_payload.get("lot_id")
        )
        exit_event_lot_ids = {
            self.live_inventory_normalized_lot_id(value)
            for value in getattr(self, "live_inventory_exit_events_logged", set())
        }
        if lot_id not in exit_event_lot_ids:
            return False
        if getattr(self, "pending_live_inventory_actual_pnl", {}):
            return False
        final_status = str(final_payload.get("final_pnl_status") or "")
        if final_status != "var_and_lighter_final_fills_confirmed":
            if not final_cycle:
                return False
            await self.append_live_inventory_log(
                "live_inventory_cycle_report",
                {
                    **final_payload,
                    "report_status": "requires_reconciliation",
                    "auto_stop": False,
                    "reason": final_status or "final_pnl_not_confirmed",
                },
            )
            self.live_inventory_cycle_report_emitted = True
            return False

        if not final_cycle:
            checkpointed = getattr(
                self,
                "live_inventory_v4_checkpointed_lot_ids",
                set(),
            )
            if lot_id not in checkpointed:
                checkpointed.add(lot_id)
                self.live_inventory_v4_checkpointed_lot_ids = checkpointed
                reconciliation_cleanup = (
                    self.clear_completed_live_inventory_cycle_reconciliation(
                        asset=str(final_payload.get("asset") or ""),
                        lot_id=final_payload.get("lot_id"),
                    )
                )
                report = {
                    **final_payload,
                    "report_status": "completed",
                    "auto_stop": False,
                    "open_lots": 0,
                    "pending_actual_pnl": 0,
                    "completed_cycles": completed_cycles,
                    "max_cycles": max_cycles,
                    "next_cycle": completed_cycles + 1,
                    "cumulative_run_pnl_usd": decimal_to_str(
                        getattr(self, "live_inventory_realized_pnl_usd", Decimal("0"))
                        - getattr(
                            self,
                            "live_inventory_v4_run_start_realized_pnl_usd",
                            Decimal("0"),
                        )
                    ),
                    "reconciliation_cleanup": reconciliation_cleanup,
                }
                await self.append_live_inventory_log(
                    "live_inventory_v4_cycle_checkpoint",
                    report,
                )
                await self.persist_live_inventory_memory(
                    reason="v4_cycle_checkpoint_completed"
                )
            return False

        reconciliation_cleanup = (
            self.clear_completed_live_inventory_cycle_reconciliation(
                asset=str(final_payload.get("asset") or ""),
                lot_id=final_payload.get("lot_id"),
            )
        )
        report = {
            **final_payload,
            "report_status": "completed",
            "auto_stop": True,
            "open_lots": 0,
            "pending_actual_pnl": len(getattr(self, "pending_live_inventory_actual_pnl", {})),
            "completed_cycles": self.live_inventory_completed_cycles,
            "max_cycles": self.live_inventory_max_cycles,
            "reconciliation_cleanup": reconciliation_cleanup,
        }
        await self.append_live_inventory_log("live_inventory_cycle_report", report)
        self.live_inventory_cycle_report_emitted = True
        await self.persist_live_inventory_memory(reason="v4_cycle_completed_auto_stop")
        self.logger.info(
            "live_inventory_v4_cycle_completed_auto_stop asset=%s cycle_id=%s final_pnl_bps=%s",
            report.get("asset"),
            report.get("lot_id"),
            report.get("final_pnl_bps"),
        )
        self.shutdown_reason = "v4_cycle_completed"
        self.stop_flag = True
        return True

    def live_inventory_v4_batch_entry_gate(
        self,
        *,
        now_monotonic: float | None = None,
    ) -> tuple[bool, str, dict[str, Any]]:
        if (
            not getattr(self, "live_inventory_basis_v4_mode", False)
            or int(getattr(self, "live_inventory_max_cycles", 1)) == 1
        ):
            return True, "ready", {}

        run_pnl_usd = (
            getattr(self, "live_inventory_realized_pnl_usd", Decimal("0"))
            - getattr(
                self,
                "live_inventory_v4_run_start_realized_pnl_usd",
                Decimal("0"),
            )
        )
        max_run_loss_usd = getattr(
            self,
            "live_inventory_basis_v4_max_run_loss_usd",
            Decimal("0.05"),
        )
        reconciliation_cleanup = (
            self.prune_checkpointed_live_inventory_reconciliation()
        )
        unresolved_final_pnl_payloads = {
            key: payload
            for key, payload in getattr(
                self,
                "pending_live_inventory_final_pnl",
                {},
            ).items()
            if not bool(payload.get("final_pnl_emitted"))
        }
        unresolved_final_pnl = len(unresolved_final_pnl_payloads)
        pending_actual_pnl = len(
            getattr(self, "pending_live_inventory_actual_pnl", {})
        )
        now = time.monotonic() if now_monotonic is None else now_monotonic
        last_exit = float(
            getattr(self, "live_inventory_v4_last_exit_monotonic", 0.0) or 0.0
        )
        cooldown_seconds = float(
            getattr(
                self,
                "live_inventory_basis_v4_cycle_cooldown_seconds",
                0.0,
            )
        )
        last_exit_reason = getattr(
            self,
            "live_inventory_v4_last_exit_reason",
            None,
        )
        if last_exit_reason == "v4_max_hold_timeout":
            cooldown_seconds = max(
                cooldown_seconds,
                float(LIVE_INVENTORY_BASIS_V4_MAX_HOLD_COOLDOWN_SECONDS),
            )
        last_exit_elapsed_seconds: float | None = (
            max(0.0, now - last_exit) if last_exit else None
        )
        if last_exit_elapsed_seconds is None:
            last_exit_at = self._parse_iso_ts(
                getattr(self, "live_inventory_v4_last_exit_at", None)
            )
            if last_exit_at is not None:
                last_exit_elapsed_seconds = max(
                    0.0,
                    (datetime.now(timezone.utc) - last_exit_at).total_seconds(),
                )
        cooldown_remaining_seconds = (
            max(0.0, cooldown_seconds - last_exit_elapsed_seconds)
            if last_exit_elapsed_seconds is not None
            else 0.0
        )
        context = {
            "completed_cycles": int(
                getattr(self, "live_inventory_completed_cycles", 0)
            ),
            "max_cycles": int(getattr(self, "live_inventory_max_cycles", 1)),
            "batch_run_pnl_usd": decimal_to_str(run_pnl_usd),
            "batch_max_run_loss_usd": decimal_to_str(max_run_loss_usd),
            "pending_actual_pnl": pending_actual_pnl,
            "unresolved_final_pnl": unresolved_final_pnl,
            "unresolved_final_pnl_keys": sorted(unresolved_final_pnl_payloads),
            "reconciliation_cleanup": reconciliation_cleanup,
            "cycle_cooldown_seconds": cooldown_seconds,
            "cooldown_remaining_seconds": round(cooldown_remaining_seconds, 3),
            "last_exit_reason": last_exit_reason,
            "last_exit_elapsed_seconds": (
                None
                if last_exit_elapsed_seconds is None
                else round(last_exit_elapsed_seconds, 3)
            ),
            "v4_episode_state": self.live_inventory_v4_episode_payload().get(
                "v4_episode_state"
            ),
            "v4_rearm_required": getattr(
                self,
                "live_inventory_v4_rearm_required",
                False,
            ),
        }
        halted_reason = getattr(
            self,
            "live_inventory_v4_batch_halted_reason",
            None,
        )
        if halted_reason:
            return False, halted_reason, context
        if max_run_loss_usd > 0 and run_pnl_usd <= -max_run_loss_usd:
            return False, "v4_batch_max_run_loss_reached", context
        if pending_actual_pnl or unresolved_final_pnl:
            return False, "v4_batch_waiting_for_reconciliation", context
        if cooldown_remaining_seconds > 0:
            return False, "v4_batch_cycle_cooldown", context
        return True, "ready", context

