    args = parser.parse_args()
    if args.mode == MODE_LIVE and not args.confirm_live:
        parser.error("--mode live requires --confirm-live")
    if args.forwarder_ws_port <= 0 or args.forwarder_ws_port > 65535:
        parser.error("--forwarder-ws-port must be between 1 and 65535")
    if args.forwarder_rest_port <= 0 or args.forwarder_rest_port > 65535:
        parser.error("--forwarder-rest-port must be between 1 and 65535")
    if args.forwarder_command_port <= 0 or args.forwarder_command_port > 65535:
        parser.error("--forwarder-command-port must be between 1 and 65535")
    forwarder_ports = {args.forwarder_ws_port, args.forwarder_rest_port, args.forwarder_command_port}
    if len(forwarder_ports) != 3:
        parser.error("forwarder ws/rest/command ports must be distinct")
    args.output_dir = Path(args.output_dir)
    if args.instance_lock_file is None:
        args.instance_lock_file = args.output_dir / INSTANCE_LOCK_FILE.name
    else:
        args.instance_lock_file = Path(args.instance_lock_file)
    if args.mode == MODE_LIVE and args.live_max_notional_usd <= 0:
        parser.error("--mode live requires --live-max-notional-usd to be set to a positive small-test limit")
    if args.auto_live_exit and not args.auto_live_entry:
        parser.error("--auto-live-exit currently requires --auto-live-entry so the runtime can track the live position it opened")
    if (args.auto_live_entry or args.auto_live_exit or args.auto_live_eager_hedge) and args.mode != MODE_LIVE:
        parser.error("--auto-live-entry/exit/eager-hedge only work in --mode live")
    if args.auto_live_entry and not args.auto_live_i_confirm_flat_start:
        parser.error("--auto-live-entry requires --auto-live-i-confirm-flat-start after manually confirming Var BTC = 0 and Lighter BTC = 0")
    if args.live_inventory:
        if args.mode != MODE_LIVE:
            parser.error("--live-inventory only works in --mode live")
        if args.auto_live_entry or args.auto_live_exit or args.auto_live_eager_hedge:
            parser.error("--live-inventory cannot be combined with --auto-live-entry/exit/eager-hedge")
        if (
            not args.live_inventory_i_confirm_flat_start
            and not args.live_inventory_i_accept_open_state_resume
            and not args.live_inventory_auto_close_manual_review_position
            and not args.live_inventory_force_close_open_state
            and not args.live_inventory_reset_state_only_after_manual_flat
        ):
            parser.error(
                "--live-inventory requires --live-inventory-i-confirm-flat-start after manually confirming flat, "
                "--live-inventory-i-accept-open-state-resume after manually confirming the saved open state matches both venues, "
                "--live-inventory-auto-close-manual-review-position for one-shot recovery, "
                "or --live-inventory-force-close-open-state for a reconciled one-shot operator exit"
            )
        live_inventory_start_modes = sum(
            bool(flag)
            for flag in (
                args.live_inventory_i_confirm_flat_start,
                args.live_inventory_i_accept_open_state_resume,
                args.live_inventory_auto_close_manual_review_position,
                args.live_inventory_force_close_open_state,
            )
        )
        if live_inventory_start_modes > 1:
            parser.error(
                "use only one of --live-inventory-i-confirm-flat-start, "
                "--live-inventory-i-accept-open-state-resume, "
                "--live-inventory-auto-close-manual-review-position, or "
                "--live-inventory-force-close-open-state"
            )
        if args.live_inventory_reset_state_only_after_manual_flat:
            if not args.live_inventory_i_confirm_flat_start:
                parser.error(
                    "--live-inventory-reset-state-only-after-manual-flat requires "
                    "--live-inventory-i-confirm-flat-start"
                )
            if (
                args.live_inventory_reset_state_after_manual_flat
                or args.live_inventory_i_accept_open_state_resume
                or args.live_inventory_auto_close_manual_review_position
                or args.live_inventory_force_close_open_state
                or args.live_inventory_maintenance_drain_after_start
                or args.live_inventory_collect_only
                or args.live_inventory_dry_decisions
            ):
                parser.error(
                    "reset-state-only mode cannot be combined with other inventory modes"
                )
        if (
            args.live_inventory_maintenance_drain_after_start
            and not args.live_inventory_i_accept_open_state_resume
        ):
            parser.error(
                "--live-inventory-maintenance-drain-after-start requires "
                "--live-inventory-i-accept-open-state-resume"
            )
        allowed_assets = {asset.strip().upper() for asset in str(args.live_allowed_assets).split(",") if asset.strip()}
        if args.live_inventory_reset_state_only_after_manual_flat:
            if len(allowed_assets) != 1:
                parser.error(
                    "reset-state-only mode requires exactly one --live-allowed-assets value"
                )
            expected_confirmation = f"FLAT:{next(iter(allowed_assets))}"
            if str(args.live_inventory_flat_reset_confirmation or "").strip().upper() != expected_confirmation:
                parser.error(
                    "reset-state-only mode requires "
                    f"--live-inventory-flat-reset-confirmation {expected_confirmation}"
                )
        if args.live_inventory_collect_only and (
            not args.live_inventory_dry_decisions
            or args.live_inventory_signal_mode != LIVE_INVENTORY_SIGNAL_BASIS
        ):
            parser.error(
                "--live-inventory-collect-only requires --live-inventory-dry-decisions "
                "and --live-inventory-signal-mode basis"
            )
        live_inventory_max_lot_notional_usd = 20
        if args.live_inventory_signal_mode == LIVE_INVENTORY_SIGNAL_BASIS:
            if not allowed_assets or not allowed_assets.issubset(LIVE_INVENTORY_BASIS_ALLOWED_ASSETS):
                parser.error(
                    "--live-inventory-signal-mode basis requires --live-allowed-assets values from "
                    f"{sorted(LIVE_INVENTORY_BASIS_ALLOWED_ASSETS)}"
                )
            if args.live_inventory_reset_state_only_after_manual_flat:
                if len(allowed_assets) != 1:
                    parser.error("reset-state-only mode requires exactly one basis asset")
            elif not args.live_inventory_dry_decisions:
                if len(allowed_assets) != 1:
                    parser.error(
                        "--live-inventory-signal-mode basis real-submit requires exactly one --live-allowed-assets value"
                    )
                if allowed_assets == {"XRP"}:
                    live_inventory_max_lot_notional_usd = 60
                if not args.live_inventory_i_accept_basis_real_diagnostic:
                    parser.error(
                        "--live-inventory-signal-mode basis real-submit requires --live-inventory-i-accept-basis-real-diagnostic"
                    )
                if args.live_inventory_lot_notional_usd <= 0 or args.live_inventory_lot_notional_usd > live_inventory_max_lot_notional_usd:
                    parser.error(
                        "basis real-submit diagnostic requires "
                        f"0 < --live-inventory-lot-notional-usd <= {live_inventory_max_lot_notional_usd}"
                    )
                if args.live_inventory_i_accept_basis_addon_diagnostic:
                    if args.live_inventory_basis_v4_real_gradient:
                        if (
                            args.live_inventory_max_lots != 0
                            or args.live_inventory_max_total_lots != 0
                        ):
                            parser.error(
                                "basis V4 real gradient requires dynamic lot limits (0)"
                            )
                    elif (
                        args.live_inventory_max_lots != 1
                        or args.live_inventory_max_total_lots < 2
                        or args.live_inventory_max_total_lots > 3
                    ):
                        parser.error(
                            "basis add-on diagnostic requires --live-inventory-max-lots 1 "
                            "and 2 <= --live-inventory-max-total-lots <= 3"
                        )
                elif args.live_inventory_max_lots != 1 or args.live_inventory_max_total_lots != 1:
                    parser.error("basis real-submit diagnostic requires --live-inventory-max-lots 1 --live-inventory-max-total-lots 1")
                continuous_v4 = bool(
                    args.live_inventory_basis_v4_profile
                    and args.live_inventory_basis_v4_continuous
                )
                if (
                    args.live_inventory_max_cycles < 0
                    or args.live_inventory_max_cycles > 10
                    or (args.live_inventory_max_cycles == 0 and not continuous_v4)
                ):
                    parser.error(
                        "basis real-submit diagnostic requires max_cycles=1..10, "
                        "or 0 with explicit continuous V4"
                    )
            elif args.live_inventory_i_accept_basis_real_diagnostic:
                parser.error("--live-inventory-i-accept-basis-real-diagnostic is only for real-submit diagnostic runs")
            elif args.live_inventory_i_accept_basis_addon_diagnostic:
                parser.error("--live-inventory-i-accept-basis-addon-diagnostic is only for real-submit diagnostic runs")
        elif allowed_assets != {"BTC"}:
            parser.error("--live-inventory V1 snapshot mode requires --live-allowed-assets BTC")
        if args.variational_submit_transport != VARIATIONAL_SUBMIT_TRANSPORT_API:
            parser.error("--live-inventory V1 requires --variational-submit-transport api")
        if args.lighter_submit_transport != LIGHTER_SUBMIT_TRANSPORT_WS:
            parser.error("--live-inventory V1 requires --lighter-submit-transport ws")
        if args.lighter_order_mode != LIGHTER_ORDER_MODE_MARKET_IOC:
            parser.error("--live-inventory V1 requires --lighter-order-mode market-ioc")
        if (
            not args.lighter_prewarm_submit_ws
            and not args.live_inventory_collect_only
            and not args.live_inventory_reset_state_only_after_manual_flat
        ):
            parser.error("--live-inventory V1 requires --lighter-prewarm-submit-ws")
        if args.live_inventory_lot_notional_usd <= 0 or args.live_inventory_lot_notional_usd > live_inventory_max_lot_notional_usd:
            parser.error(f"--live-inventory-lot-notional-usd must be > 0 and <= {live_inventory_max_lot_notional_usd} in V1")
        if (
            args.live_inventory_max_total_notional_usd <= 0
            and not args.live_inventory_basis_v4_real_gradient
        ):
            parser.error("--live-inventory-max-total-notional-usd must be > 0 in V1")
        if (
            args.live_inventory_max_lots < 0
            or (
                args.live_inventory_max_lots == 0
                and not args.live_inventory_basis_v4_real_gradient
            )
            or args.live_inventory_max_lots
            > LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_MAX_CHILD_LOTS
        ):
            parser.error(
                "--live-inventory-max-lots must be > 0 and <= "
                f"{LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_MAX_CHILD_LOTS} in V1"
            )
        if (
            args.live_inventory_max_total_lots < 0
            or (
                args.live_inventory_max_total_lots == 0
                and not args.live_inventory_basis_v4_real_gradient
            )
            or args.live_inventory_max_total_lots
            > LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_MAX_CHILD_LOTS
        ):
            parser.error(
                "--live-inventory-max-total-lots must be > 0 and <= "
                f"{LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_MAX_CHILD_LOTS} in V1"
            )
        if args.live_inventory_max_venue_leverage <= 0 or args.live_inventory_max_venue_leverage > 5:
            parser.error("--live-inventory-max-venue-leverage must be > 0 and <= 5")
        if not (
            0
            < args.live_inventory_margin_warning_pct
            < args.live_inventory_margin_block_entry_pct
            < args.live_inventory_margin_reduce_pct
            < args.live_inventory_margin_emergency_pct
            < 100
        ):
            parser.error("live inventory margin thresholds must satisfy 0 < warning < block < reduce < emergency < 100")
        if not (
            0
            < args.live_inventory_equity_balance_block_ratio
            < args.live_inventory_equity_balance_warning_ratio
            <= 1
        ):
            parser.error("live inventory equity balance ratios must satisfy 0 < block < warning <= 1")
        if args.live_inventory_entry_bps < 0:
            parser.error("--live-inventory-entry-bps must be >= 0")
        if (
            not args.live_inventory_dry_decisions
            and args.live_inventory_entry_bps < 30
            and not args.live_inventory_i_accept_diagnostic_low_entry_bps
        ):
            parser.error("--live-inventory-entry-bps must be >= 30 in V1 real-submit mode")
        if args.live_inventory_i_accept_diagnostic_low_entry_bps and args.live_inventory_dry_decisions:
            parser.error("--live-inventory-i-accept-diagnostic-low-entry-bps is only for real-submit diagnostic runs")
        if (
            args.live_inventory_ignore_recent_execution_loss_buffer_for_diagnostics
            and (args.live_inventory_dry_decisions or not args.live_inventory_i_accept_diagnostic_low_entry_bps)
        ):
            parser.error(
                "--live-inventory-ignore-recent-execution-loss-buffer-for-diagnostics requires real-submit diagnostic acknowledgement"
            )
        if args.live_inventory_exit_bps < 0:
            parser.error("--live-inventory-exit-bps must be >= 0")
        if args.live_inventory_max_var_spread_bps <= 0:
            parser.error("--live-inventory-max-var-spread-bps must be > 0")
        if args.live_inventory_max_var_snapshot_age_seconds <= 0:
            parser.error("--live-inventory-max-var-snapshot-age-seconds must be > 0")
        if args.live_inventory_dynamic_entry_buffer_bps < 0:
            parser.error("--live-inventory-dynamic-entry-buffer-bps must be >= 0")
        if args.live_inventory_max_lighter_slippage_bps < 0:
            parser.error("--live-inventory-max-lighter-slippage-bps must be >= 0")
        if args.live_inventory_lighter_submit_slippage_bps < args.live_inventory_max_lighter_slippage_bps:
            parser.error(
                "--live-inventory-lighter-submit-slippage-bps must be >= --live-inventory-max-lighter-slippage-bps"
            )
        if args.live_inventory_lighter_exit_submit_slippage_bps < args.live_inventory_max_lighter_slippage_bps:
            parser.error(
                "--live-inventory-lighter-exit-submit-slippage-bps must be >= --live-inventory-max-lighter-slippage-bps"
            )
        if args.live_inventory_max_lighter_book_age_seconds < 0:
            parser.error("--live-inventory-max-lighter-book-age-seconds must be >= 0")
        if args.live_inventory_exit_blocked_log_throttle_seconds < 0:
            parser.error("--live-inventory-exit-blocked-log-throttle-seconds must be >= 0")
        if args.live_inventory_snapshot_timeout_seconds <= 0:
            parser.error("--live-inventory-snapshot-timeout-seconds must be > 0")
        if args.live_inventory_min_hold_samples < 0:
            parser.error("--live-inventory-min-hold-samples must be >= 0")
        if args.live_inventory_max_hold_samples <= 0:
            parser.error("--live-inventory-max-hold-samples must be > 0")
        if args.live_inventory_max_unrealized_loss_bps <= 0:
            parser.error("--live-inventory-max-unrealized-loss-bps must be > 0")
        if args.live_inventory_max_cycles < 0:
            parser.error("--live-inventory-max-cycles must be >= 0 in V1")
        if (
            args.live_inventory_max_cycles == 0
            and not args.live_inventory_basis_v4_continuous
        ):
            parser.error(
                "--live-inventory-max-cycles 0 requires explicit continuous V4"
            )
        if args.live_inventory_execution_calibration:
            if args.live_inventory_signal_mode != LIVE_INVENTORY_SIGNAL_BASIS:
                parser.error("--live-inventory-execution-calibration requires --live-inventory-signal-mode basis")
            if args.live_inventory_basis_reversion or args.live_inventory_basis_v4_profile:
                parser.error(
                    "use only one of execution calibration, basis reversion, or basis V4"
                )
            if args.live_inventory_dry_decisions:
                parser.error("--live-inventory-execution-calibration is a real-submit mode and cannot use dry decisions")
            if not args.live_inventory_i_accept_execution_calibration_loss:
                parser.error(
                    "--live-inventory-execution-calibration requires --live-inventory-i-accept-execution-calibration-loss"
                )
            if args.live_inventory_max_cycles > 5:
                parser.error("--live-inventory-execution-calibration requires --live-inventory-max-cycles <= 5")
            if args.live_inventory_max_lots != 1 or args.live_inventory_max_total_lots != 1:
                parser.error("--live-inventory-execution-calibration requires max_lots=1 and max_total_lots=1")
            if args.live_inventory_lot_notional_usd > 20 or args.live_inventory_max_total_notional_usd > 25:
                parser.error("--live-inventory-execution-calibration requires lot<=20 USD and total notional<=25 USD")
            if args.live_inventory_basis_max_hold_action != "exit":
                parser.error("--live-inventory-execution-calibration requires --live-inventory-basis-max-hold-action exit")
            if args.live_inventory_min_hold_samples != args.live_inventory_max_hold_samples:
                parser.error("execution calibration requires equal min/max hold samples")
            if args.live_inventory_basis_profit_take_pnl_bps != 0:
                parser.error("execution calibration requires --live-inventory-basis-profit-take-pnl-bps 0")
            if args.live_inventory_calibration_warmup_samples <= 0:
                parser.error("--live-inventory-calibration-warmup-samples must be > 0")
            if args.live_inventory_calibration_entry_cooldown_samples <= 0:
                parser.error("--live-inventory-calibration-entry-cooldown-samples must be > 0")
            if args.live_inventory_calibration_max_run_loss_usd <= 0:
                parser.error("--live-inventory-calibration-max-run-loss-usd must be > 0")
            if args.live_inventory_calibration_max_cycle_loss_usd <= 0:
                parser.error("--live-inventory-calibration-max-cycle-loss-usd must be > 0")
        elif args.live_inventory_i_accept_execution_calibration_loss:
            parser.error(
                "--live-inventory-i-accept-execution-calibration-loss requires --live-inventory-execution-calibration"
            )
        elif (
            args.live_inventory_calibration_direction != "alternate"
            or args.live_inventory_calibration_weekdays_only
        ):
            parser.error(
                "calibration direction/time controls require --live-inventory-execution-calibration"
            )
        if args.live_inventory_basis_reversion:
            if args.live_inventory_basis_v4_profile:
                parser.error("use only one of basis reversion or basis V4")
            if args.live_inventory_signal_mode != LIVE_INVENTORY_SIGNAL_BASIS:
                parser.error("--live-inventory-basis-reversion requires --live-inventory-signal-mode basis")
            if args.live_inventory_lot_notional_usd <= 0 or args.live_inventory_lot_notional_usd > 20:
                parser.error("--live-inventory-basis-reversion requires lot notional <= 20 USD")
            if args.live_inventory_max_total_notional_usd <= 0 or args.live_inventory_max_total_notional_usd > 25:
                parser.error("--live-inventory-basis-reversion requires total notional <= 25 USD")
            if args.live_inventory_max_cycles != 1 or args.live_inventory_max_lots != 1 or args.live_inventory_max_total_lots != 1:
                parser.error("--live-inventory-basis-reversion requires max_cycles=1, max_lots=1, max_total_lots=1")
            if args.live_inventory_i_accept_basis_addon_diagnostic:
                parser.error("--live-inventory-basis-reversion does not allow basis addon diagnostics")
            if args.live_inventory_basis_use_normalized_edge_for_entry:
                parser.error("--live-inventory-basis-reversion cannot use normalized edge as the primary entry edge")
        if args.live_inventory_basis_v4_elastic_capacity and not (
            args.live_inventory_basis_v4_profile
            and args.live_inventory_basis_v4_real_gradient
        ):
            parser.error(
                "--live-inventory-basis-v4-elastic-capacity requires "
                "a V4 real-gradient profile"
            )
        if args.live_inventory_basis_v4_profile:
            if allowed_assets != {"ETH"}:
                parser.error("basis V4 profile requires --live-allowed-assets ETH")
            if args.live_inventory_execution_calibration or args.live_inventory_basis_reversion:
                parser.error(
                    "basis V4 cannot be combined with calibration or reversion"
                )
            if args.live_inventory_dry_decisions or args.live_inventory_collect_only:
                parser.error("basis V4 is a real-submit mode")
            if not args.live_inventory_i_accept_basis_v4_live:
                parser.error(
                    "basis V4 requires --live-inventory-i-accept-basis-v4-live"
                )
            if args.live_inventory_basis_v4_continuous:
                if args.live_inventory_max_cycles != 0:
                    parser.error("continuous basis V4 requires max_cycles=0")
                if not args.live_inventory_basis_v4_real_gradient:
                    parser.error("continuous basis V4 requires real gradient")
            elif (
                args.live_inventory_max_cycles < 1
                or args.live_inventory_max_cycles > 3
            ):
                parser.error("bounded basis V4 requires max_cycles between 1 and 3")
            if (
                args.live_inventory_basis_v4_test_allow_weekend
                and not args.live_inventory_basis_v4_test_skip_recent_health
            ):
                parser.error(
                    "basis V4 weekend bypass requires the explicit bounded-test health bypass"
                )
            if args.live_inventory_basis_v4_real_gradient:
                if (
                    args.live_inventory_max_lots != 0
                    or args.live_inventory_max_total_lots != 0
                ):
                    parser.error(
                        "basis V4 real gradient requires dynamic lot limits (0)"
                    )
                if args.live_inventory_basis_v4_shadow_gradient:
                    parser.error("basis V4 real gradient cannot also enable shadow gradient")
            elif args.live_inventory_max_lots != 1 or args.live_inventory_max_total_lots != 1:
                parser.error("basis V4 requires one total lot unless real gradient is enabled")
            if (
                args.live_inventory_max_cycles > 1
                and not args.live_inventory_basis_v4_test_skip_recent_health
            ):
                parser.error(
                    "multi-cycle basis V4 requires the explicit bounded-test health bypass"
                )
            if args.live_inventory_basis_v4_max_run_loss_usd < 0:
                parser.error("basis V4 max run loss must be >= 0")
            if args.live_inventory_basis_v4_reverse_test:
                if (
                    args.live_inventory_basis_v4_real_gradient
                    or args.live_inventory_basis_v4_shadow_gradient
                    or args.live_inventory_basis_v4_continuous
                ):
                    parser.error(
                        "basis V4 reverse test cannot use gradient, shadow, or continuous mode"
                    )
                if (
                    args.live_inventory_max_cycles != 1
                    or args.live_inventory_max_lots != 1
                    or args.live_inventory_max_total_lots != 1
                ):
                    parser.error(
                        "basis V4 reverse test requires one cycle and one total lot"
                    )
            if args.live_inventory_basis_v4_bidirectional:
                if args.live_inventory_basis_v4_reverse_test:
                    parser.error(
                        "basis V4 bidirectional mode cannot use reverse-test mode"
                    )
                if not (
                    args.live_inventory_basis_v4_real_gradient
                    and args.live_inventory_basis_v4_continuous
                ):
                    parser.error(
                        "basis V4 bidirectional mode requires real-gradient continuous mode"
                    )
            if (
                (
                    args.live_inventory_max_cycles > 1
                    or args.live_inventory_basis_v4_continuous
                )
                and args.live_inventory_basis_v4_max_run_loss_usd <= 0
            ):
                parser.error(
                    "multi-cycle or continuous basis V4 requires a positive max run loss"
                )
            if args.live_inventory_basis_v4_cycle_cooldown_seconds < 0:
                parser.error("basis V4 cycle cooldown must be >= 0")
            expected_total_notional = (
                0 if args.live_inventory_basis_v4_real_gradient else 25
            )
            if (
                args.live_inventory_lot_notional_usd != 20
                or args.live_inventory_max_total_notional_usd != expected_total_notional
            ):
                parser.error(
                    "basis V4 profile requires lot=20 USD and total notional="
                    f"{expected_total_notional} USD"
                )
            if args.live_inventory_i_accept_basis_addon_diagnostic != args.live_inventory_basis_v4_real_gradient:
                parser.error("basis V4 add-on acknowledgement must match real-gradient mode")
            if args.live_inventory_basis_use_normalized_edge_for_entry:
                parser.error("basis V4 requires raw executable edge")
            if args.live_inventory_basis_max_hold_action != "exit":
                parser.error("basis V4 requires max-hold action exit")
            if not args.live_inventory_basis_refresh_exit_quote_before_submit:
                parser.error("basis V4 requires refreshed exit quotes")
            if args.live_inventory_basis_profit_take_pnl_bps != 0:
                parser.error("basis V4 requires generic profit take disabled")
